package com.example.discovery.registry.model;import java.time.Instant;
public record ServiceInstance(String serviceName,String instanceId,String host,int port,String healthUrl,Instant registeredAt,Instant lastHeartbeat,ServiceInstanceStatus status){public ServiceInstance withHeartbeat(Instant at){return new ServiceInstance(serviceName,instanceId,host,port,healthUrl,registeredAt,at,status);} public static ServiceInstance from(RegisterServiceRequest r,Instant now){return new ServiceInstance(r.serviceName(),r.instanceId(),r.host(),r.port(),r.healthUrl(),now,now,ServiceInstanceStatus.UP);} }
